// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// Error carries a stable, public error code. Messages are rendered by the API
// layer, so SQL details never leave the store.
type Error struct {
	Code string
}

func (e *Error) Error() string { return "store error: " + e.Code }

// Code extracts the public code from a store error, if any.
func Code(err error) string {
	var se *Error
	if errors.As(err, &se) {
		return se.Code
	}
	return ""
}

func fail(code string) *Error { return &Error{Code: code} }

// Public error codes shared with the API layer.
const (
	CodeTenantNotFound         = "tenant_not_found"
	CodeQuotaNotFound          = "quota_not_found"
	CodeInvalidTenantInput     = "invalid_tenant_input"
	CodeTenantAlreadyExists    = "tenant_already_exists"
	CodeDuplicateMeteringEvent = "duplicate_metering_event"
	CodeQuotaExceeded          = "quota_exceeded"
	CodeTenantSuspended        = "tenant_suspended"
)

// Tenant lifecycle statuses.
const (
	StatusProvisioning = "provisioning"
	StatusActive       = "active"
	StatusSuspended    = "suspended"
	StatusArchived     = "archived"
)

var validStatuses = map[string]bool{
	StatusProvisioning: true,
	StatusActive:       true,
	StatusSuspended:    true,
	StatusArchived:     true,
}

// legalTransitions lists the destination statuses a status may move to.
// Moving to the same status is always accepted so updates stay idempotent.
var legalTransitions = map[string]map[string]bool{
	StatusProvisioning: {StatusActive: true, StatusSuspended: true, StatusArchived: true},
	StatusActive:       {StatusSuspended: true, StatusArchived: true},
	StatusSuspended:    {StatusActive: true, StatusArchived: true},
	StatusArchived:     {},
}

// Metering event sources. Reported events come from clients; throttle events are
// reservations recorded by throttle checks. They share one usage ledger.
const (
	sourceReported = "reported"
	sourceThrottle = "throttle"
)

// Tenant is the stored tenant profile.
type Tenant struct {
	ID        string `json:"tenant_id"`
	Name      string `json:"name"`
	Status    string `json:"status"`
	PlanRef   string `json:"plan_ref"`
	CreatedAt string `json:"created_at"`
	UpdatedAt string `json:"updated_at"`
}

// QuotaView is the recomputed view of one resource within one period.
type QuotaView struct {
	Resource  string `json:"resource"`
	Limit     int64  `json:"limit"`
	Used      int64  `json:"used"`
	Remaining int64  `json:"remaining"`
	Status    string `json:"status"`
}

// QuotaItem is one resource limit supplied by a quota adjustment.
type QuotaItem struct {
	Resource string
	Limit    int64
}

// MeteringInput describes one reported metering event.
type MeteringInput struct {
	TenantID   string
	EventNo    string
	Period     string
	Resource   string
	Amount     int64
	OccurredAt time.Time
}

// MeteringResult echoes the accepted event and the recomputed quota view.
type MeteringResult struct {
	TenantID   string `json:"tenant_id"`
	EventNo    string `json:"event_no"`
	Period     string `json:"period"`
	Resource   string `json:"resource"`
	Amount     int64  `json:"amount"`
	EventTime  string `json:"event_time"`
	Limit      int64  `json:"limit"`
	Used       int64  `json:"used"`
	Remaining  int64  `json:"remaining"`
	Status     string `json:"status"`
}

// ThrottleInput describes one throttle decision request.
type ThrottleInput struct {
	CheckNo  string
	Period   string
	Resource string
	Amount   int64
}

// ThrottleResult is the persisted throttle decision.
type ThrottleResult struct {
	Allowed   bool   `json:"allowed"`
	Remaining int64  `json:"remaining"`
	Status    string `json:"status"`
}

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	dsn := "file:" + path + "?" + url.Values{
		"_pragma": []string{"busy_timeout(10000)", "foreign_keys(ON)"},
	}.Encode()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	db.SetMaxOpenConns(16)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// writeTx runs fn inside a single BEGIN IMMEDIATE transaction so concurrent
// writers serialize on the reserved lock and quota checks cannot double spend.
func (s *Store) writeTx(ctx context.Context, fn func(q queryer) error) error {
	conn, err := s.db.Conn(ctx)
	if err != nil {
		return fmt.Errorf("acquire conn: %w", err)
	}
	defer conn.Close()
	if _, err := conn.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	if err := fn(conn); err != nil {
		_, _ = conn.ExecContext(ctx, "ROLLBACK")
		return err
	}
	if _, err := conn.ExecContext(ctx, "COMMIT"); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

type queryer interface {
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
}

func nowStamp() string { return time.Now().UTC().Format(time.RFC3339) }

// CreateTenant stores a new tenant profile.
func (s *Store) CreateTenant(ctx context.Context, t *Tenant) (*Tenant, error) {
	if !validStatuses[t.Status] {
		return nil, fail(CodeInvalidTenantInput)
	}
	stored := *t
	stored.CreatedAt = nowStamp()
	stored.UpdatedAt = stored.CreatedAt
	err := s.writeTx(ctx, func(q queryer) error {
		var existing string
		err := q.QueryRowContext(ctx, `SELECT id FROM tenants WHERE id = ?`, stored.ID).Scan(&existing)
		if err == nil {
			return fail(CodeTenantAlreadyExists)
		}
		if !errors.Is(err, sql.ErrNoRows) {
			return err
		}
		_, err = q.ExecContext(ctx, `
INSERT INTO tenants (id, name, status, plan_ref, created_at, updated_at)
VALUES (?, ?, ?, ?, ?, ?)`,
			stored.ID, stored.Name, stored.Status, stored.PlanRef, stored.CreatedAt, stored.UpdatedAt)
		if err != nil {
			if isUniqueViolation(err) {
				return fail(CodeTenantAlreadyExists)
			}
			return err
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return &stored, nil
}

// GetTenant reads a tenant profile.
func (s *Store) GetTenant(ctx context.Context, id string) (*Tenant, error) {
	return loadTenant(ctx, s.db, id)
}

// UpdateTenant applies a profile change and enforces legal status migration.
func (s *Store) UpdateTenant(ctx context.Context, id string, status, name, planRef *string) (*Tenant, error) {
	if status != nil && !validStatuses[*status] {
		return nil, fail(CodeInvalidTenantInput)
	}
	var updated *Tenant
