// writeTx runs fn inside an immediate transaction so writers serialize on the
// single SQLite file lock and can never double-reserve quota.
func (s *Store) writeTx(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return mapDBErr(err)
	}
	if _, err := tx.ExecContext(ctx, "ROLLBACK; BEGIN IMMEDIATE"); err != nil {
		tx.Rollback()
		return mapDBErr(err)
	}
	if err := fn(tx); err != nil {
		tx.Rollback()
		return err
	}
	if err := tx.Commit(); err != nil {
		return mapDBErr(err)
	}
	return nil
}

func mapDBErr(err error) error {
	if err == nil || errors.Is(err, sql.ErrNoRows) {
		return err
	}
	msg := err.Error()
	if strings.Contains(msg, "constraint failed") || strings.Contains(msg, "UNIQUE") {
		return fmt.Errorf("%w: %s", ErrDuplicate, msg)
	}
	if strings.Contains(msg, "SQLITE_BUSY") {
		return fmt.Errorf("%w: database busy", ErrStorage)
	}
	return fmt.Errorf("%w: %s", ErrStorage, msg)
}

