// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	dsn := "file:" + url.PathEscape(path) + "?_pragma=busy_timeout(5000)&_pragma=foreign_keys(1)"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	db.SetMaxOpenConns(8)
	db.SetMaxIdleConns(4)
	db.SetConnMaxIdleTime(5 * time.Minute)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error {
	if err := s.db.Ping(); err != nil {
		return ErrStorageUnavailable
	}
	return nil
}

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

// CreateTenant inserts a new tenant profile.
func (s *Store) CreateTenant(ctx context.Context, t Tenant) (Tenant, error) {
	now := nowStamp()
	t.CreatedAt = now
	t.UpdatedAt = now
	_, err := s.db.ExecContext(ctx,
		`INSERT INTO tenants (id, name, state, plan_ref, created_at, updated_at)
		 VALUES (?, ?, ?, ?, ?, ?)`,
		t.ID, t.Name, t.State, t.PlanRef, t.CreatedAt, t.UpdatedAt)
	if err != nil {
		if isUniqueViolation(err) {
			return Tenant{}, ErrDuplicateTenant
		}
		return Tenant{}, err
	}
	return t, nil
}

// GetTenant loads a tenant profile.
func (s *Store) GetTenant(ctx context.Context, id string) (Tenant, error) {
	var t Tenant
	err := s.db.QueryRowContext(ctx,
		`SELECT id, name, state, plan_ref, created_at, updated_at FROM tenants WHERE id = ?`, id).
		Scan(&t.ID, &t.Name, &t.State, &t.PlanRef, &t.CreatedAt, &t.UpdatedAt)
	if errors.Is(err, sql.ErrNoRows) {
		return Tenant{}, ErrTenantNotFound
	}
	if err != nil {
		return Tenant{}, err
	}
	return t, nil
}

// UpdateTenant applies a legal state migration and optional name/plan edits.
func (s *Store) UpdateTenant(ctx context.Context, id string, name, planRef, state *string) (Tenant, error) {
	var result Tenant
	err := s.tx(ctx, func(tx *sql.Tx) error {
		var current Tenant
		err := tx.QueryRowContext(ctx,
			`SELECT id, name, state, plan_ref, created_at, updated_at FROM tenants WHERE id = ?`, id).
			Scan(&current.ID, &current.Name, &current.State, &current.PlanRef, &current.CreatedAt, &current.UpdatedAt)
		if errors.Is(err, sql.ErrNoRows) {
			return ErrTenantNotFound
		}
		if err != nil {
			return err
		}
		next := current
		if name != nil {
			next.Name = *name
		}
		if planRef != nil {
			next.PlanRef = *planRef
		}
		if state != nil {
			if !ValidState(*state) || !TransitionAllowed(current.State, *state) {
				return ErrInvalidState
			}
			next.State = *state
		}
		next.UpdatedAt = nowStamp()
		if _, err := tx.ExecContext(ctx,
			`UPDATE tenants SET name = ?, state = ?, plan_ref = ?, updated_at = ? WHERE id = ?`,
			next.Name, next.State, next.PlanRef, next.UpdatedAt, id); err != nil {
			return err
		}
		result = next
		return nil
	})
	if err != nil {
		return Tenant{}, err
	}
	return result, nil
}

// PutQuota appends a change record for one tenant/period/resource, upserts the
// active limit and returns the quota recomputed against current usage.
func (s *Store) PutQuota(ctx context.Context, tenantID, period, resource string, limit int64) (Quota, QuotaChange, error) {
	var q Quota
	var change QuotaChange
	err := s.tx(ctx, func(tx *sql.Tx) error {
		if err := requireWritableTenant(ctx, tx, tenantID); err != nil {
			return err
		}
		var oldLimit sql.NullInt64
		var existed bool
		row := tx.QueryRowContext(ctx,
			`SELECT limit_amount FROM quotas WHERE tenant_id = ? AND period = ? AND resource = ?`,
			tenantID, period, resource)
		var scanned int64
		switch err := row.Scan(&scanned); {
		case err == nil:
			oldLimit = sql.NullInt64{Int64: scanned, Valid: true}
			existed = true
		case errors.Is(err, sql.ErrNoRows):
		default:
			return err
		}

		used, err := sumUsage(ctx, tx, tenantID, period, resource)
		if err != nil {
			return err
		}
		if limit < used {
			return ErrQuotaExceeded
		}

		if existed {
			if _, err := tx.ExecContext(ctx,
				`UPDATE quotas SET limit_amount = ?, updated_at = ?
				 WHERE tenant_id = ? AND period = ? AND resource = ?`,
				limit, nowStamp(), tenantID, period, resource); err != nil {
				return err
			}
		} else {
			if _, err := tx.ExecContext(ctx,
				`INSERT INTO quotas (tenant_id, period, resource, limit_amount, created_at, updated_at)
				 VALUES (?, ?, ?, ?, ?, ?)`,
				tenantID, period, resource, limit, nowStamp(), nowStamp()); err != nil {
				return err
			}
		}

		var seq int64
		if err := tx.QueryRowContext(ctx,
			`SELECT COALESCE(MAX(change_seq), 0) + 1 FROM quota_changes
			 WHERE tenant_id = ? AND period = ? AND resource = ?`,
			tenantID, period, resource).Scan(&seq); err != nil {
			return err
		}
		change = QuotaChange{
			Period:    period,
			Resource:  resource,
			OldLimit:  oldLimit.Int64,
			NewLimit:  limit,
			ChangedAt: nowStamp(),
			ChangeSeq: seq,
		}
		if _, err := tx.ExecContext(ctx,
			`INSERT INTO quota_changes
			 (tenant_id, period, resource, old_limit, new_limit, changed_at, change_seq)
			 VALUES (?, ?, ?, ?, ?, ?, ?)`,
			tenantID, period, resource, oldLimit.Int64, limit, change.ChangedAt, seq); err != nil {
			return err
		}
		q = buildQuota(period, resource, limit, used)
		return nil
	})
	if err != nil {
		return Quota{}, QuotaChange{}, err
	}
	return q, change, nil
}

// ListQuotas returns every resource quota for one tenant/period.
func (s *Store) ListQuotas(ctx context.Context, tenantID, period string) ([]Quota, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT q.period, q.resource, q.limit_amount,
		        COALESCE((SELECT SUM(amount) FROM metering_events e
		                  WHERE e.tenant_id = q.tenant_id AND e.period = q.period
		                    AND e.resource = q.resource), 0) AS used
		 FROM quotas q
		 WHERE q.tenant_id = ? AND q.period = ?
		 ORDER BY q.resource`, tenantID, period)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []Quota
	for rows.Next() {
		var periodName, resource string
		var limit, used int64
		if err := rows.Scan(&periodName, &resource, &limit, &used); err != nil {
			return nil, err
		}
		out = append(out, buildQuota(periodName, resource, limit, used))
	}
	return out, rows.Err()
}

// GetQuota returns the quota for one tenant/period/resource.
func (s *Store) GetQuota(ctx context.Context, tenantID, period, resource string) (Quota, error) {
	q, err := scanOneQuota(s.db.QueryRowContext(ctx,
