		FROM tenants WHERE id = ?`, id)
	return scanTenant(row)
}

func scanTenant(row *sql.Row) (Tenant, error) {
	var t Tenant
	if err := row.Scan(&t.ID, &t.Name, &t.Status, &t.PlanRef, &t.CreatedAt, &t.UpdatedAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
