func newTestRouter(t *testing.T) (http.Handler, *store.Store) {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	return NewRouter(st), st
}

func doJSON(t *testing.T, router http.Handler, method, path string, body any) (int, map[string]any) {
	t.Helper()
	var reader *bytes.Reader
	if body != nil {
		raw, _ := json.Marshal(body)
		reader = bytes.NewReader(raw)
	} else {
		reader = bytes.NewReader(nil)
	}
	req := httptest.NewRequest(method, path, reader)
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()
	router.ServeHTTP(rec, req)
	var decoded map[string]any
	if rec.Body.Len() > 0 {
		if err := json.Unmarshal(rec.Body.Bytes(), &decoded); err != nil {
			t.Fatalf("decode %s: %v body=%s", path, err, rec.Body.String())
		}
	}
	return rec.Code, decoded
}

func requireError(t *testing.T, code int, body map[string]any, wantStatus int, wantCode string) {
	t.Helper()
	if code != wantStatus {
		t.Fatalf("status = %d want %d body=%v", code, wantStatus, body)
	}
	errObj, ok := body["error"].(map[string]any)
	if !ok || len(body) != 1 {
		t.Fatalf("error envelope wrong: %v", body)
	}
	if errObj["code"] != wantCode {
		t.Fatalf("code = %v want %s", errObj["code"], wantCode)
	}
	if msg, _ := errObj["message"].(string); msg == "" {
		t.Fatalf("message empty: %v", errObj)
	}
	if len(errObj) != 2 {
		t.Fatalf("error object must have only code and message: %v", errObj)
	}
}

func TestTenantLifecycleAndIsolation(t *testing.T) {
	router, _ := newTestRouter(t)

	status, body := doJSON(t, router, http.MethodPost, "/v1/tenants", map[string]any{
		"id": "t1", "name": "Shop One", "plan_ref": "plan-basic",
	})
	if status != http.StatusCreated || body["id"] != "t1" || body["status"] != "provisioning" {
		t.Fatalf("create: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodGet, "/v1/tenants/t1", nil)
	if status != http.StatusOK || body["name"] != "Shop One" || body["plan_ref"] != "plan-basic" {
		t.Fatalf("read: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodPost, "/v1/tenants", map[string]any{
		"id": "t1", "name": "Dup", "plan_ref": "p",
	})
	requireError(t, status, body, http.StatusConflict, "tenant_already_exists")

	status, body = doJSON(t, router, http.MethodGet, "/v1/tenants/missing", nil)
	requireError(t, status, body, http.StatusNotFound, "tenant_not_found")

	status, body = doJSON(t, router, http.MethodPost, "/v1/tenants", map[string]any{
		"id": "t2", "name": "Bad", "status": "weird", "plan_ref": "p",
	})
	requireError(t, status, body, http.StatusBadRequest, "invalid_tenant_input")

	status, body = doJSON(t, router, http.MethodPost, "/v1/tenants", map[string]any{
		"id": "no space", "name": "x", "plan_ref": "p",
	})
	requireError(t, status, body, http.StatusBadRequest, "invalid_tenant_input")

	status, body = doJSON(t, router, http.MethodPut, "/v1/tenants/t1", map[string]any{"status": "active"})
	if status != http.StatusOK || body["status"] != "active" {
		t.Fatalf("activate: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodPut, "/v1/tenants/t1", map[string]any{"status": "provisioning"})
	requireError(t, status, body, http.StatusConflict, "invalid_tenant_input")

	status, body = doJSON(t, router, http.MethodPut, "/v1/tenants/t1", map[string]any{"status": "suspended"})
	if status != http.StatusOK {
		t.Fatalf("suspend: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodPut, "/v1/tenants/t1/quotas", map[string]any{
		"period": "2026-10", "resource": "orders", "limit": 10,
	})
	requireError(t, status, body, http.StatusForbidden, "tenant_suspended")

	status, body = doJSON(t, router, http.MethodGet, "/v1/tenants/t1", nil)
	if status != http.StatusOK || body["status"] != "suspended" {
		t.Fatalf("suspended read should work: %d %v", status, body)
	}
}

func TestQuotaMeteringUsageConsistency(t *testing.T) {
	router, _ := newTestRouter(t)

	status, _ := doJSON(t, router, http.MethodPost, "/v1/tenants", map[string]any{
		"id": "t1", "name": "Shop", "status": "active", "plan_ref": "p",
	})
	if status != http.StatusCreated {
		t.Fatalf("create status %d", status)
	}

	status, body := doJSON(t, router, http.MethodPut, "/v1/tenants/t1/quotas", map[string]any{
		"period": "2026-10", "resource": "orders", "limit": 10,
	})
	if status != http.StatusOK || body["used"].(float64) != 0 || body["remaining"].(float64) != 10 || body["status"] != "ok" {
		t.Fatalf("put quota: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodPut, "/v1/tenants/t1/quotas", map[string]any{
		"period": "2026-10", "quotas": []map[string]any{{"resource": "api_calls", "limit": 5}},
	})
	if status != http.StatusOK {
		t.Fatalf("bulk quota: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodGet, "/v1/tenants/t1/quotas?period=2026-10", nil)
	if status != http.StatusOK {
		t.Fatalf("get quotas: %d", status)
	}
	quotas := body["quotas"].([]any)
	if len(quotas) != 2 {
		t.Fatalf("quotas = %v", quotas)
	}

	status, body = doJSON(t, router, http.MethodGet, "/v1/tenants/nope/quotas?period=2026-10", nil)
	requireError(t, status, body, http.StatusNotFound, "tenant_not_found")

	status, body = doJSON(t, router, http.MethodGet, "/v1/tenants/t1/quotas?period=2099-01", nil)
	requireError(t, status, body, http.StatusNotFound, "quota_not_found")

	// 8 of 10 consumed -> warning (<=20% remaining).
	status, body = doJSON(t, router, http.MethodPost, "/v1/metering/events", map[string]any{
		"tenant_id": "t1", "event_no": "e1", "period": "2026-10",
		"resource": "orders", "amount": 8,
	})
	if status != http.StatusCreated || body["used"].(float64) != 8 || body["status"] != "warning" {
		t.Fatalf("event e1: %d %v", status, body)
	}

	status, body = doJSON(t, router, http.MethodPost, "/v1/metering/events", map[string]any{
		"tenant_id": "t1", "event_no": "e1", "period": "2026-10",
		"resource": "orders", "amount": 8,
	})
	requireError(t, status, body, http.StatusConflict, "duplicate_metering_event")

	status, body = doJSON(t, router, http.MethodPost, "/v1/metering/events", map[string]any{
		"tenant_id": "t1", "event_no": "e2", "period": "2026-10",
		"resource": "orders", "amount": 3,
	})
	requireError(t, status, body, http.StatusConflict, "quota_exceeded")

	status, body = doJSON(t, router, http.MethodPost, "/v1/metering/events", map[string]any{
		"tenant_id": "ghost", "event_no": "e2", "period": "2026-10",
		"resource": "orders", "amount": 1,
	})
	requireError(t, status, body, http.StatusNotFound, "tenant_not_found")

	status, body = doJSON(t, router, http.MethodPost, "/v1/metering/events", map[string]any{
		"tenant_id": "t1", "event_no": "e3", "period": "2026-10",
		"resource": "api_calls", "amount": 99,
	})
	requireError(t, status, body, http.StatusConflict, "quota_exceeded")

	status, quotaBody := doJSON(t, router, http.MethodGet, "/v1/tenants/t1/quotas?period=2026-10", nil)
	status, usageBody := doJSON(t, router, http.MethodGet, "/v1/tenants/t1/usage?period=2026-10", nil)
	if status != http.StatusOK {
		t.Fatalf("usage status %d", status)
	}
	qByResource := map[string]map[string]any{}
	for _, raw := range quotaBody["quotas"].([]any) {
		line := raw.(map[string]any)
		qByResource[line["resource"].(string)] = line
	}
	for _, raw := range usageBody["usage"].([]any) {
		line := raw.(map[string]any)
		resource := line["resource"].(string)
		q := qByResource[resource]
		if line["used"] != q["used"] || line["remaining"] != q["remaining"] ||
			line["limit"] != q["limit"] || line["status"] != q["status"] {
			t.Fatalf("usage/quota mismatch for %s: %v vs %v", resource, line, q)
		}
	}
}

